'use strict';
// One journey owns two independently queried legs. Older plans remain readable.
const V11={leg:'all',returnTransport:'',returnVias:'',weatherSnapshot:null};
function v11Date(t){return new Date(/Z$|[+]\d\d:\d\d$/.test(t)?t:t+':00+08:00')}
function v11Local(t){return new Date(v11Date(t).getTime()+8*3600000).toISOString().slice(0,16)}
function v11Departure(p){return p?.planned||p?.created||V2.at}
const v11DraftBase=vDraft;
vDraft=function(){v11DraftBase();const t=document.getElementById('v11-return-transport'),v=document.getElementById('v11-return-vias');if(t)V11.returnTransport=t.value;if(v)V11.returnVias=v.value;for(const [id,key] of [['v5-return','returnAt'],['v5-stay','stay']]){const el=document.getElementById(id);if(el)V5[key]=key==='stay'?Math.max(0,Math.min(1440,Number(el.value)||0)):el.value}};
const v11FormBase=v8Form;
v8Form=function(){let h=v11FormBase();if(!V5.round)return h;const arrangement=`<div class="v11return"><h3>返程安排</h3><p><b>返程起点：</b>${esc(V2.destination||'请填写去程目的地')}<br><b>返程终点：</b>${esc(V2.origin||'请填写去程出发点')}</p><div class="field"><label for="v11-return-transport">返程交通方式</label><select id="v11-return-transport">${['公共交通','驾车','步行'].map(t=>`<option ${t===(V11.returnTransport||V2.transport)?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="v11-return-vias">返程途经点（用分号分隔，可留空）</label><input id="v11-return-vias" value="${esc(V11.returnVias)}" placeholder="例如：文锦；黄贝岭"></div><small>查询后同时保留两程。未填返程时刻时，仅在去程有有效到达时间时按停留时长推算；历史驾车或停运须指定返程时刻。</small></div>`;return h.replace('<div class="field"><label>目的地停留',arrangement+'<div class="field"><label>目的地停留').replace('查询并添加出行方案','查询并添加往返方案')};
function v11Group(p=vFocus()){if(!p)return [];return p.journeyId?V2.plans.filter(x=>x.journeyId===p.journeyId):[p]}
function v11MapPlans(){const ps=V8.compare?V2.plans.filter(p=>V2.selected.includes(p.id)):v11Group();return ps.filter(p=>V11.leg==='all'||(p.leg||'outbound')===V11.leg)}
function v11Markers(p){const names=[p.origin,...(p.vias||[]),p.destination];const out=(p.coords||[]).map((c,i)=>({lat:c?.lat,lon:c?.lon,label:(p.leg==='return'?'返程':'去程')+' · '+(i===0?'起点':i===names.length-1?'终点':'途经点 '+i)+'：'+names[i]}));if(p.transport==='步行')(p.walkSnaps||[]).forEach((c,i)=>{if(c.distance>=30)out.push({...c,label:'步行路径接入点 '+(i+1)+'（距参考地点约'+Math.round(c.distance)+'米）'})});(p.segments||[]).forEach((g,i)=>{const a=R10.stations.find(s=>s.name===g.from),b=R10.stations.find(s=>s.name===g.to);if(a)out.push({...a,label:(p.leg==='return'?'返程':'去程')+' · '+(i?'换乘':'上车')+'：'+g.from});if(b&&i===p.segments.length-1)out.push({...b,label:(p.leg==='return'?'返程':'去程')+' · 下车：'+g.to})});return out.filter(c=>Number.isFinite(c.lat)&&Number.isFinite(c.lon))}
const v11PlanBase=v8Plan;
v8Plan=function(p,i){return v11PlanBase(p,i).replace('方案 '+(i+1)+' ·', (p.leg==='return'?'返程':'去程')+'方案 '+(i+1)+' ·').replace('</article>',(typeof v17WalkDetail==='function'?v17WalkDetail(p):'')+'</article>').replace('<div class="v8plandetail">',`<small class="v11plantime">出发：${esc(dateText(v11Departure(p)))}</small><div class="v8plandetail">`)};
async function v11BuildLeg(spec,seq){const coords=[spec.origin,...spec.vias,spec.destination].map(vResolve);const plan={...spec,id:vId(),coords,duration:null,distance:null,geometry:null,roadNames:[]};if(coords.some(c=>!c||!Number.isFinite(c.lat)||!Number.isFinite(c.lon)||c.regionOnly))return {...plan,coords:[],label:'地址未匹配到具体坐标，路径未取得',unavailable:true};if(spec.transport==='步行'){if(spec.leg==='return'&&!spec.planned)return {...plan,label:'返程出发时刻未设置，请指定后查询',unavailable:true};return typeof v17BuildWalkingLeg==='function'?v17BuildWalkingLeg(plan,coords,seq):{...plan,label:'步行路由组件未加载',unavailable:true};}if(spec.leg==='return'&&!spec.planned)return {...plan,label:'返程时刻未取得，请指定时间后重新查询',unavailable:true};if(spec.transport==='公共交通')return v10TransitPlan(plan,coords);try{const r=await fetch(`https://router.project-osrm.org/route/v1/driving/${coords.map(c=>c.lon+','+c.lat).join(';')}?alternatives=3&overview=full&geometries=geojson&steps=true`,{signal:AbortSignal.timeout(18000)});if(!r.ok)throw Error('路线服务未返回');const o=await r.json();if(o.code!=='Ok'||!o.routes?.length)throw Error('道路路径未取得');return o.routes.slice(0,3).map(r=>({...plan,id:vId(),geometry:r.geometry,geometryBasis:'current-reference',duration:r.duration,distance:r.distance,label:spec.mode==='history'?'当前道路参考轨迹 · 非历史灾时路由与时长':'OSRM道路参考 · 不含实时洪涝与拥堵',roadNames:[...new Set((r.legs||[]).flatMap(l=>(l.steps||[]).map(s=>s.name).filter(Boolean)))]}));}catch(e){const cache=coords.length===2&&R10.driving_samples?.find(s=>s.from===coords[0].name&&s.to===coords[1].name);if(cache)return cache.routes.map(r=>({...plan,id:vId(),...r,geometryBasis:'current-reference',label:'已缓存2026-10-12道路参考，不含历史灾时路况'}));return {...plan,label:e.message+'；路径与时长未取得',unavailable:true}}}
vAddPlan=async function(){vDraft();if(V2.loading)return;if(!V2.origin.trim()||!V2.destination.trim())return toast('请填写起点和目的地');const departure=V2.departure==='planned'?V2.planned:(V2.mode==='history'?V2.at:businessNow().toISOString());if(!departure||!Number.isFinite(v11Date(departure).getTime())||(V2.departure==='planned'&&v11Date(departure)<businessNow())){V2.error='请选择不早于当前业务时刻的出发时间';vRender();return}const config={enabled:V5.round,stay:V5.stay,purpose:V5.purpose,returnAt:V5.returnAt,returnTransport:V11.returnTransport||V2.transport,returnVias:V11.returnVias.split(/[;；]/).map(s=>s.trim()).filter(Boolean)};if(config.enabled&&config.returnAt&&v11Date(config.returnAt)<=v11Date(departure)){V2.error='返程时刻必须晚于去程出发时刻';vRender();return}const seq=++V2.requestSeq,journeyId=vId(),spec={snapshotVersion:19,queryWeather:V2.weather?JSON.parse(JSON.stringify(V2.weather)):null,journeyId,leg:'outbound',origin:V2.origin,destination:V2.destination,vias:V2.vias.filter(Boolean),transport:V2.transport,mode:V2.mode,at:V2.mode==='history'?V2.at:null,eventId:V2.eventId,planned:departure,created:businessNow().toISOString(),actual_created_at:new Date().toISOString(),roundTrip:config};V2.loading=true;V2.error='';vRender();try{const outbound=[await v11BuildLeg(spec,seq)].flat();if(seq!==V2.requestSeq)return;let back=[];if(config.enabled){const p=outbound.find(p=>p.duration!=null&&!p.blocked),validArrival=p&&!(p.mode==='history'&&['驾车','步行'].includes(p.transport));const returnAt=config.returnAt||(validArrival?v11Local(new Date(v11Date(departure).getTime()+p.duration*1000+config.stay*60000).toISOString()):'');back=[await v11BuildLeg({...spec,leg:'return',origin:spec.destination,destination:spec.origin,vias:config.returnVias,transport:config.returnTransport,planned:returnAt},seq)].flat()}if(seq!==V2.requestSeq)return;const all=[...outbound,...back];all.forEach(p=>{if(V9.active)p.scenario={test:true,scene:V9.scene,asof:spec.at};v5Base.commit(p)});V2.focus=outbound[0].id;V11.leg='all';if(all.some(p=>p.unavailable))V2.error='部分方案资料未取得，已分别保留两程状态。请核对地址、返程时刻和服务覆盖。';}finally{if(seq===V2.requestSeq){V2.loading=false;vRender()}}};
const v11RestoreBase=vRestore;
vRestore=function(p,c=false){const group=p?.journeyId?stored('sy-v2-history').filter(x=>x.journeyId===p.journeyId):[];v11RestoreBase(p,c);if(p?.roundTrip){V11.returnTransport=p.roundTrip.returnTransport||'';V11.returnVias=(p.roundTrip.returnVias||[]).join('；')}if(group.length){if(!c&&V2.focus===p.id){V2.plans=group;V2.selected=group.map(x=>x.id)}else if(V2.plans.some(x=>x.id===p.id)){group.forEach(x=>{if(!V2.plans.some(q=>q.id===x.id))V2.plans.push(x);if(!V2.selected.includes(x.id))V2.selected.push(x.id)})}}if(!c&&V2.focus===p?.id&&group.length){const out=group.find(x=>x.leg==='outbound');if(out)Object.assign(V2,{origin:out.origin,destination:out.destination,vias:[...(out.vias||[])],transport:out.transport,planned:out.planned,departure:'planned'})}V11.leg='all';vRender()};
const v11SnapshotBase=vSnapshot;
vSnapshot=function(p){const s=v11SnapshotBase(p);if(p?.journeyId)s.plans=stored('sy-v2-history').filter(x=>x.journeyId===p.journeyId);return s};
// Replace all three previous risk summaries with one table and its evidence.
v8Summary=function(){const rows=v11Group().slice().sort((a,b)=>(a.leg==='return')-(b.leg==='return')),back=rows.some(p=>p.leg==='return'),round=rows[0]?.roundTrip?.enabled||V5.round,official=V2.mode==='history'?vEvents().find(e=>e.record_id==='SZ-E022'):null,blocked=rows.some(p=>p.blocked),hazards=rows.filter(p=>vRisks(p).length);return `<section class="v8summary v11risk"><div class="v8sectionhead"><span class="v8step">3</span><h2>${round?'往返':'行程'}风险与安排</h2><span class="tag gray">${V2.mode==='history'?'当时公开资料':'当前参考资料'}</span></div>${rows.length?`<div class="tablewrap"><table><thead><tr><th>行程与时间</th><th>运营与路线</th><th>已关联依据</th><th>天气参考</th></tr></thead><tbody>${rows.map(p=>`<tr><td><b>${p.leg==='return'?'返程':'去程'}</b><br>${esc(p.origin)} → ${esc(p.destination)}<br>${p.planned?esc(dateText(p.planned)):'未设置出发时刻'}</td><td>${esc(p.transport)}<br>${p.blocked?'关联区段暂停地铁客运，不能采用此方案':p.unavailable?esc(p.label):'已生成参考路径'}${p.mode==='history'?'<br><small>地图使用当前地理背景</small>':''}</td><td>防汛指引：${vRisks(p).length}条<br>反馈线索：${vFeedback(p).length}条<br>公开公告：${vRelated(p).length}条</td><td>小时降水（${esc(V2.weather?.place||V5.weatherPlace)}）：${esc(p.mode==='history'?'历史记录未提供此地点逐小时数值':v5RainAt(p.planned))}<br>${typeof v18RainPanel==='function'?v18RainPanel(p):typeof v12Help==='function'?v12Help('危险概率：暂无可靠数值 ⓘ',RISK_HELP):'危险概率：暂无可靠数值'}</td></tr>`).join('')}${round?`<tr><td>目的地停留</td><td colspan="3">${Number(rows[0]?.roundTrip?.stay??V5.stay)}分钟${back?' · 返程已单独查询':' · 返程尚未生成'}</td></tr>`:''}</tbody></table></div>`:'<p>查询行程后，这里分别展示两程的运营影响、具体隐患和安排建议。</p>'}<section class="v15hazardsection"><h3>具体隐患与运营影响</h3>${rows.map(p=>`<div><h4>${p.leg==='return'?'返程':'去程'} · ${esc(p.origin)} → ${esc(p.destination)}</h4>${vRelated(p).map(e=>`<p data-original>${(typeof v17ExplainText==='function'?v17ExplainText(typeof v12EventText==='function'?v12EventText(e):e.summary):esc(typeof v12EventText==='function'?v12EventText(e):e.summary))} ${v9AsOfLink(e)}</p>`).join('')}${typeof v12Hazards==='function'?v12Hazards(p):vRisks(p).map(r=>`<p>${esc(r.risk_description)}</p>`).join('')}</div>`).join('')||'<p>等待关联你的行程。</p>'}</section>${hazards.length?`<div class="v12hazardintro"><b>长期隐患是什么？</b><p>${esc(typeof HAZARD_HELP!=='undefined'?HAZARD_HELP:'防汛指引中列出的低洼、易积水地点或路段。')}</p></div>`:''}<div class="v11advice"><h3>安排建议</h3>${blocked?'<p><b>调整交通安排：</b>此次地铁方案涉及已发布的停运区段。取消该段乘车安排；非必要行程延后，必要行程优先远程联系目的地。</p>':''}${official?`<p><b>当时官方建议：</b>${esc(official.summary)}</p>${v9AsOfLink(official)}`:rows.length?`<p>${hazards.length?'路线名称关联到防汛指引中的易积水地点，优先避开上方列出的低洼区段；可修改途经点生成另一条参考方案。':'现有防汛指引中暂无这些地点的专项记录。地图提供路线参考，暂无覆盖此行程的积水观测。'}</p>`:'<p>填写起终点和出发时间后即可查询；返程可独立选择交通方式。</p>'}${round&&!back?'<p><b>补齐返程：</b>填写返程出发时刻后重新查询完整往返。</p>':''}</div><details class="v8analysis"><summary>数据范围与判断方式</summary><p>已逐项整理本行程关联的公开公告及防汛指引。名称关联表示资料提及该地点或道路，不代表已经测量整条路线。道路水深和实时交通仍需要对应观测；强降雨概率使用独立的集合天气预报。</p></details><div class="v8summaryfoot"><small>资料截止与两程出发时刻分别保留。</small><button data-v5="report" data-value="往返风险与依据">导出${round?'往返':'行程'}报告</button></div></section>`};
const v11DashboardBase=vDashboard;
vDashboard=function(){const ps=V8.compare?V2.plans.filter(p=>V2.selected.includes(p.id)):v11Group(),hasBack=ps.some(p=>p.leg==='return');if(!hasBack&&V11.leg==='return')V11.leg='outbound';if(!ps.length)V11.leg='outbound';const controls=`<div class="v11maptoolbar"><div class="v11mapcontrols" role="group" aria-label="地图行程">${[['outbound','去程'],['return','返程'],['all','往返对比']].map(([k,t])=>`<button data-v11="map-leg" data-value="${k}" aria-pressed="${!!ps.length&&V11.leg===k}" class="${ps.length&&V11.leg===k?'active':''}" ${(!ps.length||k!=='outbound'&&!hasBack)?'disabled title="查询完整往返后可用"':''}>${t}</button>`).join('')}</div><small>${hasBack?'两程分别显示；可合并比较':ps.length?'单程方案 · 未安排返程':'查询后显示路线与起终点'}</small></div>`;return v11DashboardBase().replace('<div id="v8-route-map"',`${controls}<p class="v11mapnote">${v11MapPlans().length?'地图对应已保存方案。':'填写行程并查询，地图会同步更新。'}</p><div id="v8-route-map"`)};
document.addEventListener('click',e=>{const b=e.target.closest('[data-v11]');if(b?.dataset.v11==='map-leg'){vDraft();if(b.dataset.value!=='outbound'&&!v11Group().some(p=>p.leg==='return'))return;V11.leg=b.dataset.value;V8.signature='';vRender()}});
document.addEventListener('input',e=>{if(V2.loading&&(['v2-origin','v2-destination','v2-planned','v5-return','v5-stay','v11-return-vias'].includes(vFormId(e.target))||e.target.dataset?.via!=null)){V2.requestSeq++;V2.loading=false;const b=document.querySelector('.v8querybutton');if(b){b.disabled=false;b.textContent='输入已修改，重新查询'}}if(['v2-origin','v2-destination'].includes(vFormId(e.target))){const n=document.querySelector('.v11mapnote');if(n)n.textContent='行程输入已修改；地图仍显示已保存方案，请重新查询以同步新行程。'}});
// Weather reports use an immutable, weather-only snapshot, never the journey snapshot.
const WEATHER_FIELDS=[['data','天气数据'],['trend','趋势图'],['table','数据表'],['warning','气象预警与专业判断']];
function v11WeatherSnapshot(){const historical=V2.mode==='history';return {scope:'weather',mode:V2.mode,at:V2.at,created:new Date().toISOString(),place:historical?V5.weatherPlace:(V2.weather?.place||V5.weatherPlace),weather:historical?null:V2.weather?JSON.parse(JSON.stringify(V2.weather)):null,facts:historical?vEvents().filter(e=>/雨量|预警|专业预测/.test(e.category)):[],plans:[]}}
function v11WeatherParts(s,c){const w=s.weather,parts=[{title:'地点、时段与来源',text:`天气地点：${s.place}\n资料截止／查询：${s.mode==='history'?dateText(s.at):dateText(s.created)}\n数据时刻：${w?.current?.time||'未取得'}\n数据刷新：${w?.fetchedAt?dateText(w.fetchedAt):'未取得'}\n模型官方发布时间：未取得；刷新时间不是发布时间\n来源：${s.mode==='history'?'以下历史气象资料分别标注来源与发布时间':'Open-Meteo模型天气 https://open-meteo.com/；非站点实测、非官方预警'}`}];if(c.data)parts.push({title:'天气数据',text:w?.current?`数据匹配地点：${w.place}\n气温：${w.current.temperature_2m??'未取得'} °C\n降水量：${w.current.precipitation??'未取得'} mm\n风速：${w.current.wind_speed_10m??'未取得'} m/s`:s.facts.filter(e=>/雨量/.test(e.category)).map(e=>`${e.place_text}：${e.summary}\n发布：${dateText(e.source_published_at)}\n来源：${e.source_url}`).join('\n\n')||'该地点当时数值未取得。其他站点报道不能当作本地点观测。'});if(c.trend)parts.push({title:'趋势图',text:w?.hourly?'逐小时模型天气；降水单位mm，气温单位°C。':'未取得当时连续观测／数值预报，不使用事后ERA5冒充当时趋势。'});if(c.table)parts.push({title:'数据表',text:w?.hourly?w.hourly.time.map((t,i)=>({t,i})).filter(x=>x.t>=(w.current?.time||'')).slice(0,24).map(({t,i})=>`${t}（北京时间） | 气温：${w.hourly.temperature_2m?.[i]??'未取得'} °C | 小时降水：${w.hourly.precipitation?.[i]??'未取得'} mm | 降水概率：${w.hourly.precipitation_probability?.[i]??'未取得'} %`).join('\n'):'逐小时数据未取得。'});if(c.warning)parts.push({title:'气象预警与专业判断',text:s.facts.filter(e=>/预警|专业预测/.test(e.category)).map(e=>`${e.summary}\n发布：${dateText(e.source_published_at)}\n来源：${e.source_url}`).join('\n\n')||'此模式下没有已接入的动态官方预警，需核对深圳气象官方发布 https://weather.sz.gov.cn/'});return parts}
const v11ExportDialogBase=v10ExportDialog;
v10ExportDialog=function(record=null,label='查询报告'){if(!/天气/.test(label)){V11.weatherSnapshot=null;return v11ExportDialogBase(record,label)}vExportRecord=null;V10.exportLabel=label;V11.weatherSnapshot=v11WeatherSnapshot();vDialog('天气报告 · 选择内容',`<form id="v11-weather-export"><div class="field"><label>报告标题</label><input name="event" value="深雨知路 · 天气报告" required></div><div class="exportchoices">${WEATHER_FIELDS.map(([id,t])=>`<label><input name="${id}" type="checkbox" ${id==='data'?'checked':''}>${t}</label>`).join('')}</div><label>格式<select name="format">${['pdf','html','txt','png'].map(x=>`<option value="${x}">${x.toUpperCase()}</option>`).join('')}</select></label><p>固定保留地点、时段、来源、源时间、导出时间与品牌水印。</p><button class="primary">预览天气报告</button></form>`)};
const v11ReportBase=v10ReportHtml;
v10ReportHtml=function(r){if(r.s.scope!=='weather')return v11ReportBase(r);return `<div class="v10reportpaper" style="width:820px;padding:38px;background:white;color:#203644;font:14px/1.8 sans-serif"><b>深雨知路 · RAINWISE</b><h1>${esc(r.event)}</h1><p>导出时间：${esc(dateText(r.exported))}</p>${r.parts.map(p=>`<section><h2>${esc(p.title)}</h2><div style="white-space:pre-wrap">${esc(p.text)}</div>${p.title==='趋势图'&&r.trendMarkup?r.trendMarkup:''}</section>`).join('')}<p>深雨知路 · RAINWISE · 气象资料报告</p></div>`};
function v11TrendMarkup(s){const old=V2.weather,mode=V2.mode;try{V2.weather=s.weather;V2.mode=s.mode;return v5Trend().replace(/<details>[\s\S]*?<\/details>/,'')}finally{V2.weather=old;V2.mode=mode}}
document.addEventListener('submit',e=>{if(vFormId(e.target)!=='v11-weather-export')return;e.preventDefault();const c=Object.fromEntries(new FormData(e.target));if(!WEATHER_FIELDS.some(([id])=>c[id]))return toast('请选择至少一项天气内容');const s=V11.weatherSnapshot;V10.report={event:c.event,chosen:c,s,parts:v11WeatherParts(s,c),trendMarkup:c.trend?v11TrendMarkup(s):'',exported:new Date().toISOString()};vDialog('天气报告预览',`<div class="v10reportpreview">${v10ReportHtml(V10.report)}</div><button class="primary" data-v10="download-report">确认导出 ${esc(c.format.toUpperCase())}</button><button data-v10="reselect">重新选择内容</button>`)});
// Weather and journey exports share the guarded exporter in repairs.js.

// Selecting a return card views that leg while keeping the outbound form canonical.
document.addEventListener('click',e=>{const b=e.target.closest('[data-v2="focus"]');if(!b)return;const p=V2.plans.find(x=>x.id===b.dataset.value);if(!p?.journeyId)return;e.preventDefault();e.stopImmediatePropagation();vDraft();const out=V2.plans.find(x=>x.journeyId===p.journeyId&&x.leg==='outbound')||p;V2.focus=p.id;Object.assign(V2,{origin:out.origin,destination:out.destination,vias:[...(out.vias||[])],transport:out.transport,planned:out.planned,departure:'planned'});if(out.roundTrip){Object.assign(V5,{round:out.roundTrip.enabled,stay:out.roundTrip.stay,returnAt:out.roundTrip.returnAt,purpose:out.roundTrip.purpose});V11.returnTransport=out.roundTrip.returnTransport;V11.returnVias=(out.roundTrip.returnVias||[]).join('；')}V11.leg=p.leg||'outbound';V8.signature='';vRender()},true);
const v11PartsBase=vExportParts;
vExportParts=function(s,c){const parts=v11PartsBase(s,c);if(c.plans&&s.plans?.some(p=>p.journeyId))parts.push({title:'往返安排与各程状态',text:s.plans.map(p=>`${p.leg==='return'?'返程':'去程'}：${p.origin} → ${p.destination}；交通方式：${p.transport}\n出发：${p.planned?dateText(p.planned):'未取得'}；资料截止：${dateText(p.at)}\n${p.label}\n${p.blocked?'停运影响，无有效到达时间':p.mode==='history'?'灾时到达时间未取得':'参考时长：'+(p.duration!=null?Math.ceil(p.duration/60)+'分钟':'未取得')}`).join('\n\n')});if(c.plans&&s.plans?.some(p=>p.transport==='步行'&&p.walkSteps?.length))parts.push({title:'步行路段与来源',text:s.plans.filter(p=>p.transport==='步行').map(p=>`${p.origin} → ${p.destination}\n${p.label}\n参考距离 ${p.distance!=null?(p.distance/1000).toFixed(2)+'公里':'未取得'}\n${(p.walkSteps||[]).map(x=>x.instruction+' · '+Math.round(x.distance)+'米').join('\n')}\n来源 https://routing.openstreetmap.de/about.html`).join('\n\n')});return parts};
vRender();

const v11SceneBase=v9Start;
v9Start=function(...args){V11.leg='all';V11.returnTransport='';V11.returnVias='';return v11SceneBase(...args)};
